import { $ } from "bun";
import { existsSync, mkdirSync } from "node:fs";
import { join, resolve } from "node:path";

export const ROOT = resolve(import.meta.dir, "..", "..");
export const OUT = join(ROOT, "obj", "aphrody");
export const VS_INSTALLER_DIR = "C:\\Program Files (x86)\\Microsoft Visual Studio\\Installer";
export const VSWHERE = join(VS_INSTALLER_DIR, "vswhere.exe");
export const LOCALAPPDATA =
  process.env.LOCALAPPDATA ?? join(process.env.USERPROFILE ?? "C:\\Users\\Default", "AppData", "Local");
export const PACKAGE_NAME = "WindowsTerminalDev";
export const LAYOUT_DIR = join(LOCALAPPDATA, "aphrody", "terminal", "layout");
export const CANONICAL_SETTINGS = "C:\\aphrody\\tools\\config\\host\\windows\\terminal\\settings.json";
/** Generated by aphrody-identity (crates/ui/identity/src/terminal_theme.rs). */
export const M3_SCHEMES = "C:\\aphrody\\tools\\config\\host\\windows\\terminal\\aphrody-m3.wt-scheme.json";
export const FRAGMENT_DIR = join(LOCALAPPDATA, "Microsoft", "Windows Terminal", "Fragments", "Aphrody");

export function ensureDir(path: string): string {
  mkdirSync(path, { recursive: true });
  return path;
}

export function log(step: string, msg: string): void {
  console.log(`[${step}] ${msg}`);
}

export interface VsInstance {
  instanceId: string;
  installationPath: string;
  installationVersion: string;
  productId: string;
  displayName: string;
  packages?: { id: string; version: string; type: string }[];
}

export async function vsInstance(): Promise<VsInstance | undefined> {
  if (!existsSync(VSWHERE)) return undefined;
  const all = (await $`${VSWHERE} -all -prerelease -products ${"*"} -include packages -format json -utf8`
    .quiet()
    .json()) as VsInstance[];
  // Prefer a full IDE over Build Tools, then the newest version.
  const rank = (i: VsInstance) => (i.productId.endsWith(".BuildTools") ? 0 : 1);
  return all.sort((a, b) => rank(b) - rank(a) || Bun.semver.order(b.installationVersion, a.installationVersion))[0];
}

export async function isAdmin(): Promise<boolean> {
  return (await $`net session`.nothrow().quiet()).exitCode === 0;
}

/** argv prefix that runs a command elevated without a console prompt, or undefined when none is usable. */
export function elevator(): string[] | undefined {
  const gsudo = Bun.which("gsudo");
  if (gsudo) return [gsudo, "--direct"];
  const sudo = Bun.which("sudo", { PATH: "C:\\Windows\\System32" });
  if (sudo) return [sudo, "--inline"];
  return undefined;
}

export function msbuildExe(vs: VsInstance): string {
  const exe = join(vs.installationPath, "MSBuild", "Current", "Bin", "amd64", "MSBuild.exe");
  if (!existsSync(exe)) throw new Error(`MSBuild introuvable (${exe})`);
  return exe;
}

let vsEnvCache: Record<string, string> | undefined;

/** Environment of a VS Developer prompt (amd64), equivalent to Set-MsBuildDevEnvironment. */
export async function vsDevEnv(vs: VsInstance): Promise<Record<string, string>> {
  if (vsEnvCache) return vsEnvCache;
  const devcmd = join(vs.installationPath, "Common7", "Tools", "VsDevCmd.bat");
  const proc = Bun.spawn(
    ["cmd.exe", "/d", "/s", "/c", `"call "${devcmd}" -arch=amd64 -host_arch=amd64 -no_logo >nul && set"`],
    {
      // VsDevCmd's helper scripts call a bare `vswhere.exe`.
      env: { ...process.env, PATH: `${VS_INSTALLER_DIR};${process.env.PATH ?? ""}` },
      stdout: "pipe",
      stderr: "inherit",
      windowsVerbatimArguments: true,
    },
  );
  const text = await proc.stdout.text();
  if ((await proc.exited) !== 0) throw new Error(`VsDevCmd.bat a échoué (${devcmd})`);
  // GitHub runners hand cmd both `Path` and `PATH`; MSBuild's ToolTask throws on case-insensitive duplicates.
  // VsDevCmd prepends to the one it updates, so the longest value is kept.
  const env: Record<string, string> = {};
  const keyOf = new Map<string, string>();
  for (const line of text.split(/\r?\n/)) {
    const eq = line.indexOf("=");
    if (eq <= 0) continue;
    const name = line.slice(0, eq);
    const value = line.slice(eq + 1);
    const key = keyOf.get(name.toUpperCase()) ?? name;
    keyOf.set(name.toUpperCase(), key);
    if (!(key in env) || value.length > env[key].length) env[key] = value;
  }
  const vcpkg = join(vs.installationPath, "VC", "vcpkg");
  if (!env.VCPKG_ROOT && existsSync(join(vcpkg, "vcpkg.exe"))) env.VCPKG_ROOT = vcpkg;
  // GitHub-hosted Windows images ship a standalone vcpkg.
  if (!env.VCPKG_ROOT && env.VCPKG_INSTALLATION_ROOT) env.VCPKG_ROOT = env.VCPKG_INSTALLATION_ROOT;
  vsEnvCache = env;
  return env;
}

/** Runs a command, tees stdout/stderr into `logFile`, returns the exit code. */
export async function runLogged(
  cmd: string[],
  opts: { cwd?: string; env?: Record<string, string>; logFile: string },
): Promise<number> {
  const sink = Bun.file(opts.logFile).writer();
  sink.write(`> ${cmd.join(" ")}\n`);
  const proc = Bun.spawn(cmd, { cwd: opts.cwd ?? ROOT, env: opts.env, stdout: "pipe", stderr: "pipe" });
  const pump = async (stream: ReadableStream<Uint8Array>, out: NodeJS.WriteStream) => {
    for await (const chunk of stream) {
      sink.write(chunk);
      out.write(chunk);
    }
  };
  await Promise.all([pump(proc.stdout, process.stdout), pump(proc.stderr, process.stderr)]);
  const code = await proc.exited;
  await sink.end();
  return code;
}

export async function pwsh(script: string): Promise<{ code: number; out: string }> {
  const exe = Bun.which("pwsh") ?? "powershell.exe";
  const r = await $`${exe} -NoProfile -NonInteractive -Command ${script}`.nothrow().quiet();
  return { code: r.exitCode, out: r.stdout.toString() + r.stderr.toString() };
}

export function windowsTargetPlatformVersion(): Promise<string> {
  return Bun.file(join(ROOT, "src", "common.build.pre.props"))
    .text()
    .then(t => /<WindowsTargetPlatformVersion[^>]*>([\d.]+)</.exec(t)?.[1] ?? "10.0.26100.0");
}
